impl TryFrom<ThermostatClusterPatch> for ThermostatCluster {
    type Error = ClusterError;

    #[inline]
    fn try_from(patch: ThermostatClusterPatch) -> Result<Self, Self::Error> {
        crate::traits::PartialCluster::try_into_full(patch)
    }
}

impl crate::traits::ClusterSpec for ThermostatCluster {
    type Attribute = Attribute;
    type Command = Command;
    type CommandResponse = CommandResponse;
    type Event = ();
    type Features = u32;
    type Patch = ThermostatClusterPatch;

    const CLUSTER_ID: ClusterId = Self::CLUSTER_ID;
    const CLUSTER_REVISION: u16 = Self::CLUSTER_REVISION;
    const IS_EMPTY: bool = false;
    const NAME: &'static str = Self::NAME;

    #[inline]
    fn apply_patch(&mut self, patch: Self::Patch) {
        Self::apply_patch(self, patch);
    }
}

